const A='/assets/';
const app=document.querySelector('#app');
const db=window.EA_SUPABASE;
const nav=[['home','⌂','Beranda'],['planning','☷','Planning'],['goals','◎','Goals'],['journal','✎','Journal'],['ideas','✦','Ideas'],['projects','□','Projects'],['works','▣','Karya'],['journey','↗','Journey'],['profile','◉','Profile']];
const focusOptions=['Karya','Bisnis','Karier','Pendidikan','Kehidupan','Kreativitas'];
let state={session:null,user:null,profile:null,selected:[],onStep:1,active:'home',loading:false,cache:{goals:[],tasks:[],journal:[],ideas:[],projects:[],works:[],settings:null},publicWorks:null,publicQuery:''};
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const msg=(text,type='error')=>`<div class="notice ${type}">${esc(text)}</div>`;
const DEFAULT_BG=A+'splash.jpg';
function initials(){return esc((state.profile?.name||'EA').trim().slice(0,2).toUpperCase())}
function mediaUrl(url,fallback=''){return url||fallback}
async function uploadProfileMedia(kind,input){const file=input?.files?.[0];if(!file||!state.user)return; if(!file.type.startsWith('image/')){alert('Pilih file gambar.');return} if(file.size>5*1024*1024){alert('Ukuran maksimal 5 MB.');return} const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';const path=`${state.user.id}/${kind}.${ext}`; const {error}=await db.storage.from('profile-media').upload(path,file,{upsert:true,contentType:file.type}); if(error){alert(error.message);return} const {data}=db.storage.from('profile-media').getPublicUrl(path); const field=kind==='avatar'?'avatar_url':'background_url'; const {error:e}=await db.from('profiles').update({[field]:data.publicUrl,updated_at:new Date().toISOString()}).eq('id',state.user.id); if(e){alert(e.message);return} state.profile={...state.profile,[field]:data.publicUrl}; renderApp();}
async function resetBackground(){if(!state.user)return;const {error}=await db.from('profiles').update({background_url:null,updated_at:new Date().toISOString()}).eq('id',state.user.id);if(error){alert(error.message);return}state.profile={...state.profile,background_url:null};renderApp()}
async function loadSession(){const {data,error}=await db.auth.getSession();if(error)throw error;state.session=data.session;state.user=data.session?.user||null;if(state.user){const {data:p}=await db.from('profiles').select('*').eq('id',state.user.id).maybeSingle();state.profile=p||{id:state.user.id,name:state.user.user_metadata?.name||'Kreator',username:state.user.user_metadata?.username||'',email:state.user.email};state.selected=state.profile.focus||[]}}
function splash(){app.innerHTML=`<div class="splash"><img class="bg" src="${A}splash.jpg"><div class="content"><img class="logo" src="${A}logoea.png"><div class="word">EA PLAN</div><div class="tag">YOUR PERSONALIZED PLANNING JOURNEY</div></div></div>`;setTimeout(()=>{document.querySelector('.splash')?.classList.add('hide');setTimeout(()=>state.session?dashboard():welcome(),650)},3000)}
function welcome(){app.innerHTML=`<div class="authShell"><div class="authVisual"><img src="${A}splash.jpg"><div class="visualText"><div class="ey">PLAN · CREATE · REFLECT · GROW</div><h1>Rancang hidupmu.<br>Rawat perjalananmu.</h1><p>Ruang untuk merencanakan langkah, menyimpan ide, menulis cerita, mengelola proyek, dan melihat pertumbuhan dari waktu ke waktu.</p></div></div><div class="authPanel"><div class="authBox"><img class="miniLogo" src="${A}logoea.png"><div class="brandText">EA PLAN</div><h2>Mulai perjalananmu.</h2><p class="sub">Satu langkah kecil hari ini dapat menjadi bagian dari karya besar esok hari.</p><div class="form"><button class="goldBtn" onclick="register()">Buat Akun</button><button class="ghostBtn" onclick="login()">Sudah punya akun? Masuk</button></div><p class="switch">Ruang privatmu tersimpan aman di akun EA PLAN.</p></div></div></div>`}
function auth(mode,notice=''){const reg=mode==='register';app.innerHTML=`<div class="authPanel authFull"><div class="authBox"><img class="miniLogo" src="${A}logoea.png"><div class="brandText">EA PLAN</div><h2>${reg?'Buat akun.':'Selamat datang kembali.'}</h2><p class="sub">${reg?'Buat ruang perjalanan pribadimu.':'Masuk untuk melanjutkan perjalananmu.'}</p>${notice?msg(notice,'info'):''}<form class="form" onsubmit="submitAuth(event,'${mode}')">${reg?'<input class="input" id="name" placeholder="Nama" required><input class="input" id="username" placeholder="Username" required>':''}<input class="input" id="email" type="email" placeholder="Email" autocomplete="email" required><input class="input" id="password" type="password" placeholder="Password" minlength="6" autocomplete="current-password" required><div id="err"></div><button class="goldBtn" type="submit">${reg?'Buat Akun':'Masuk'}</button></form><div class="switch"><button class="link" onclick="welcome()">← Kembali</button> · <button class="link" onclick="forgot()">Lupa password?</button></div></div></div>`}
function register(){auth('register')}function login(){auth('login')}
async function submitAuth(e,mode){e.preventDefault();const er=document.querySelector('#err');er.innerHTML='';const email=document.querySelector('#email').value.trim().toLowerCase(),password=document.querySelector('#password').value;if(mode==='register'){const name=document.querySelector('#name').value.trim(),username=document.querySelector('#username').value.trim();const {data,error}=await db.auth.signUp({email,password,options:{data:{name,username}}});if(error){er.innerHTML=msg(error.message);return}if(!data.session){auth('login','Akun berhasil dibuat. Periksa emailmu untuk verifikasi, lalu masuk.');return}await loadSession();onboarding()}else{const {data,error}=await db.auth.signInWithPassword({email,password});if(error){er.innerHTML=msg(error.message);return}state.session=data.session;state.user=data.user;await loadSession();if(state.profile?.onboarding_completed)dashboard();else onboarding()}}
function forgot(){app.innerHTML=`<div class="authPanel authFull"><div class="authBox"><div class="brandText">EA PLAN</div><h2>Reset password.</h2><p class="sub">Masukkan email untuk menerima instruksi pemulihan.</p><form class="form" onsubmit="sendReset(event)"><input class="input" id="resetEmail" type="email" placeholder="Email" required><div id="resetErr"></div><button class="goldBtn">Kirim instruksi</button></form><div class="switch"><button class="link" onclick="login()">← Kembali ke login</button></div></div></div>`}
async function sendReset(e){e.preventDefault();const el=document.querySelector('#resetErr');const email=document.querySelector('#resetEmail').value.trim().toLowerCase();const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin});el.innerHTML=error?msg(error.message):msg('Instruksi reset telah dikirim jika email tersebut terdaftar.','success')}
function onboarding(){state.onStep=1;renderOnboarding()}
function renderOnboarding(){const body=state.onStep===1?`<div class="kicker">LANGKAH 1</div><h2>Apa yang ingin kamu kembangkan?</h2><p class="sub">Pilih yang paling dekat dengan perjalananmu. Kamu bisa memilih lebih dari satu.</p><div class="choices">${focusOptions.map(x=>`<button class="choice ${state.selected.includes(x)?'selected':''}" onclick="pick('${x}')">${state.selected.includes(x)?'✓':'○'} ${x}</button>`).join('')}</div>`:state.onStep===2?`<div class="kicker">LANGKAH 2</div><h2>Ceritakan sedikit tentangmu.</h2><p class="sub">Bagian ini opsional. Profil dapat kamu ubah nanti.</p><textarea class="input" id="bio" rows="6" placeholder="Apa yang sedang kamu perjuangkan atau bangun?">${esc(state.profile?.bio||'')}</textarea>`:`<div class="kicker">LANGKAH 3</div><h2>Apa target utamamu?</h2><p class="sub">Kita mulai dari satu target yang benar-benar berarti.</p><input class="input" id="firstGoal" placeholder="Contoh: menyelesaikan karya pertama saya">`;app.innerHTML=`<div class="onboard"><div class="onboardBox"><div class="brandText">EA PLAN</div><div class="steps"><i class="${state.onStep>=1?'active':''}"></i><i class="${state.onStep>=2?'active':''}"></i><i class="${state.onStep>=3?'active':''}"></i></div>${body}<div class="actions">${state.onStep>1?'<button class="ghostBtn" onclick="state.onStep--;renderOnboarding()">Kembali</button>':''}<button class="goldBtn" onclick="nextOnboard()">${state.onStep<3?'Lanjut':'Masuk ke EA PLAN'}</button></div></div></div>`}
function pick(x){state.selected=state.selected.includes(x)?state.selected.filter(y=>y!==x):[...state.selected,x];renderOnboarding()}
async function nextOnboard(){if(state.onStep===1&&!state.selected.length){alert('Pilih minimal satu fokus.');return}if(state.onStep<3){if(state.onStep===2&&document.querySelector('#bio'))state.profile={...(state.profile||{}),bio:document.querySelector('#bio').value};state.onStep++;renderOnboarding();return}const bio=document.querySelector('#bio')?.value??state.profile?.bio??'';const firstGoal=document.querySelector('#firstGoal')?.value.trim();const p={id:state.user.id,name:state.profile?.name||state.user.user_metadata?.name,username:state.profile?.username||state.user.user_metadata?.username,email:state.user.email,bio,focus:state.selected,onboarding_completed:true,updated_at:new Date().toISOString()};const {error}=await db.from('profiles').upsert(p);if(error){alert(error.message);return}state.profile={...state.profile,...p};if(firstGoal){const {error:e}=await db.from('goals').insert({user_id:state.user.id,title:firstGoal,progress:0,status:'active'});if(e)alert(e.message)}dashboard()}
async function loadData(){if(!state.user)return;const uid=state.user.id;const [g,t,j,i,p,w,set]=await Promise.all([db.from('goals').select('*').eq('user_id',uid).order('created_at',{ascending:false}),db.from('tasks').select('*').eq('user_id',uid).order('created_at',{ascending:false}),db.from('journal_entries').select('*').eq('user_id',uid).order('created_at',{ascending:false}),db.from('ideas').select('*').eq('user_id',uid).order('created_at',{ascending:false}),db.from('projects').select('*').eq('user_id',uid).order('created_at',{ascending:false}),db.from('works').select('*').eq('user_id',uid).order('created_at',{ascending:false}),db.from('app_settings').select('*').eq('id',1).maybeSingle()]);state.cache={goals:g.data||[],tasks:t.data||[],journal:j.data||[],ideas:i.data||[],projects:p.data||[],works:w.data||[],settings:set.data||null}}
async function dashboard(){await loadData();state.active='home';renderApp()}
function renderApp(){const n=nav.find(x=>x[0]===state.active)||nav[0];let content=state.active==='home'?home():state.active==='planning'?planning():state.active==='goals'?goals():state.active==='journal'?journal():state.active==='ideas'?ideas():state.active==='projects'?projects():state.active==='works'?works():state.active==='journey'?journey():profile();const avatar=state.profile?.avatar_url?`<img src="${esc(state.profile.avatar_url)}" alt="Profil">`:initials();app.innerHTML=`<div class="appShell"><aside class="side"><div class="sideBrand"><img src="${A}logoea.png"><span>EA PLAN</span></div><nav class="nav">${nav.map(x=>`<button class="${x[0]===state.active?'active':''}" onclick="go('${x[0]}')">${x[1]}&nbsp;&nbsp;${x[2]}</button>`).join('')}<button onclick="logout()">↪&nbsp;&nbsp;Keluar</button></nav></aside><main class="main"><header class="top"><div><div class="kicker">RUANG PERJALANAN</div><h2>${n[2]}</h2></div><div class="avatar">${avatar}</div></header>${content}</main><nav class="mobileNav">${[['home','⌂','Beranda'],['planning','☷','Plan'],['goals','◎','Goals'],['journey','↗','Journey'],['profile','◉','Profil']].map(x=>`<button class="${x[0]===state.active?'active':''}" onclick="go('${x[0]}')"><b>${x[1]}</b>${x[2]}</button>`).join('')}</nav></div>`} 
function home(){const c=state.cache,g=c.goals.length,progress=g?Math.round(c.goals.reduce((s,x)=>s+x.progress,0)/g):0;return `<div class="grid"><article class="card wide"><div class="kicker">SELAMAT DATANG, ${esc((state.profile?.name||'KREATOR').toUpperCase())}</div><h1 class="heroTitle">Rancang hidupmu.<br>Rawat perjalananmu.</h1><p class="muted">“${esc(c.settings?.daily_quote||'Setiap karya besar berawal dari satu langkah kecil yang terencana.')}”</p></article><article class="card"><div class="kicker">PROGRESS</div><div class="metric">${progress}%</div><div class="progress"><i style="width:${progress}%"></i></div><p class="muted">Rata-rata target aktifmu.</p></article><article class="card"><div class="kicker">TARGET AKTIF</div><div class="metric">${g}</div><p class="muted">Tujuan yang sedang kamu jalankan.</p></article></div>${publicHome()}`} 
function planning(){return `<div class="grid"><article class="card full"><div class="kicker">PLANNING</div><h1 class="pageTitle">Susun langkah dengan sederhana.</h1><form class="inlineForm" onsubmit="addTask(event)"><input class="input lightInput" id="taskTitle" placeholder="Tambahkan prioritas..." required><input class="input lightInput" id="taskDate" type="date"><button class="goldBtn">Tambah</button></form>${state.cache.tasks.map(t=>`<div class="item taskRow"><span class="${t.completed?'strike':''}">${t.completed?'✓':'○'} ${esc(t.title)} ${t.due_date?`<small>${esc(t.due_date)}</small>`:''}</span><div><button class="smallBtn" onclick="completeTask('${t.id}')">${t.completed?'Batal':'Selesai'}</button><button class="smallBtn danger" onclick="removeItem('tasks','${t.id}')">Hapus</button></div></div>`).join('')||'<p class="muted">Belum ada planning.</p>'}</article></div>`}
function goals(){return `<div class="grid"><article class="card full"><div class="kicker">GOALS</div><h1 class="pageTitle">Ubah mimpi menjadi target.</h1><form class="form lightForm" onsubmit="addGoal(event)"><input class="input lightInput" id="goalTitle" placeholder="Judul target" required><input class="input lightInput" id="goalDate" type="date"><textarea class="input lightInput" id="goalDesc" rows="3" placeholder="Deskripsi singkat"></textarea><button class="goldBtn">Tambah target</button></form>${state.cache.goals.map(g=>`<div class="item"><div class="itemHead"><strong>${esc(g.title)}</strong><span>${g.progress}%</span></div><div class="progress"><i style="width:${g.progress}%"></i></div><div class="rowActions"><input type="range" min="0" max="100" value="${g.progress}" oninput="updateGoalProgress('${g.id}',this.value)"><button class="smallBtn" onclick="toggleGoal('${g.id}', '${g.status}')">${g.status==='completed'?'Aktifkan':'Selesai'}</button><button class="smallBtn danger" onclick="removeItem('goals','${g.id}')">Hapus</button></div></div>`).join('')||'<p class="muted">Belum ada target.</p>'}</article></div>`}
function journal(){return moduleCRUD('journal','JOURNAL','Tulis apa yang terjadi, dirasakan, dan dipelajari.','Judul catatan','Tulis ceritamu...')}
function ideas(){return moduleCRUD('ideas','IDEAS','Tangkap ide sebelum hilang.','Judul ide','Catatan ide...')}
function moduleCRUD(type,kickerText,desc,titlePh,bodyPh){const arr=state.cache[type];return `<div class="grid"><article class="card full"><div class="kicker">${kickerText}</div><h1 class="pageTitle">${esc(desc)}</h1><form class="form lightForm" onsubmit="addTextItem(event,'${type}')"><input class="input lightInput" id="itemTitle" placeholder="${esc(titlePh)}" required><textarea class="input lightInput" id="itemBody" rows="4" placeholder="${esc(bodyPh)}"></textarea><button class="goldBtn">Simpan</button></form>${arr.map(x=>`<div class="item"><strong>${esc(x.title||'Tanpa judul')}</strong><p class="muted">${esc(x.body||'')}</p><button class="smallBtn danger" onclick="removeItem('${type}','${x.id}')">Hapus</button></div>`).join('')||'<p class="muted">Belum ada catatan.</p>'}</article></div>`}
function projects(){return `<div class="grid"><article class="card full"><div class="kicker">PROJECTS</div><h1 class="pageTitle">Pecah karya besar menjadi tahapan kecil.</h1><form class="form lightForm" onsubmit="addProject(event)"><input class="input lightInput" id="projectTitle" placeholder="Nama project" required><textarea class="input lightInput" id="projectDesc" rows="3" placeholder="Deskripsi"></textarea><button class="goldBtn">Buat project</button></form>${state.cache.projects.map(p=>`<div class="item"><div class="itemHead"><strong>${esc(p.title)}</strong><span>${p.progress}%</span></div><p class="muted">${esc(p.description||'')}</p><div class="progress"><i style="width:${p.progress}%"></i></div><div class="rowActions"><input type="range" min="0" max="100" value="${p.progress}" oninput="updateProjectProgress('${p.id}',this.value)"><button class="smallBtn danger" onclick="removeItem('projects','${p.id}')">Hapus</button></div></div>`).join('')||'<p class="muted">Belum ada project.</p>'}</article></div>`}
function journey(){const c=state.cache,g=c.goals.length,avg=g?Math.round(c.goals.reduce((s,x)=>s+x.progress,0)/g):0;return `<div class="grid"><article class="card wide"><div class="kicker">JOURNEY</div><h1 class="pageTitle">Pertumbuhanmu, dari waktu ke waktu.</h1><p class="muted">Progress rata-rata target saat ini.</p><div class="metric">${avg}%</div><div class="progress"><i style="width:${avg}%"></i></div></article><article class="card"><div class="kicker">CATATAN</div><div class="metric">${c.journal.length}</div><span class="muted">Refleksi yang tersimpan.</span></article><article class="card full"><h3>Target perjalanan</h3>${c.goals.map(x=>`<div class="item"><div class="itemHead"><span>${esc(x.title)}</span><strong>${x.progress}%</strong></div></div>`).join('')||'<div class="item">Mulai dengan membuat target pertama.</div>'}</article></div>`}
function profile(){const p=state.profile||{};const avatar=p.avatar_url?`<img src="${esc(p.avatar_url)}" alt="Foto profil">`:`<span>${initials()}</span>`;const bg=mediaUrl(p.background_url,DEFAULT_BG);return `<div class="profilePage"><section class="profileHero" style="background-image:linear-gradient(180deg,rgba(23,19,15,.18),rgba(23,19,15,.76)),url('${esc(bg)}')"><div class="profileHeroInner"><div class="kicker lightKicker">EA PLAN</div><h1>Profil</h1><p>Kenali dirimu, atur langkahmu, wujudkan masa depanmu.</p></div></section><article class="profileCard card full"><div class="profileIdentity"><div class="profileAvatar">${avatar}<label class="cameraBtn" title="Ganti foto profil">⌕<input type="file" accept="image/*" onchange="uploadProfileMedia('avatar',this)"></label></div><div><div class="kicker">SELAMAT DATANG</div><h2>${esc(p.name||'Kreator')}</h2><p class="muted">@${esc(p.username||'username')}</p></div></div><div class="profileActions"><label class="mediaBtn">Ganti background<input type="file" accept="image/*" onchange="uploadProfileMedia('background',this)"></label><button class="smallBtn" onclick="resetBackground()">Background default</button></div><form class="form lightForm" onsubmit="saveProfile(event)"><label class="label lightLabel">Nama</label><input class="input lightInput" id="pName" value="${esc(p.name||'')}" required><label class="label lightLabel">Username</label><input class="input lightInput" id="pUsername" value="${esc(p.username||'')}" required><label class="label lightLabel">Bio</label><textarea class="input lightInput" id="pBio" rows="5">${esc(p.bio||'')}</textarea><button class="goldBtn">Simpan profil</button></form><section class="moreMenu"><div class="kicker">LAINNYA</div><button onclick="go('ideas')"><b>✦</b><span><strong>Ideas</strong><small>Kumpulkan dan kelola ide-ide brilian</small></span><i>›</i></button><button onclick="go('projects')"><b>□</b><span><strong>Projects</strong><small>Kelola proyek dan pantau progres</small></span><i>›</i></button><button onclick="go('journal')"><b>✎</b><span><strong>Journal</strong><small>Tulis catatan dan refleksi harian</small></span><i>›</i></button></section><button onclick="go('works')"><b>▣</b><span><strong>Karya Publik</strong><small>Buat, terbitkan, dan baca karya pengguna lain</small></span><i>›</i></button></section>${p.email&&state.cache.settings?.owner_email&&p.email===state.cache.settings.owner_email?`<section class="moreMenu ownerTools"><div class="kicker">PEMILIK APLIKASI</div><form class="form lightForm" onsubmit="saveDailyQuote(event)"><textarea class="input lightInput" id="dailyQuote" rows="3">${esc(state.cache.settings.daily_quote||'')}</textarea><button class="goldBtn">Simpan Quote Harian</button></form></section>`:''}<button class="ghostBtn darkGhost" onclick="logout()">Keluar dari EA PLAN</button></article></div>`}

let workDraft={id:null};
function publicHome(){const works=(state.publicWorks||[]);return `<section class="publicLibrary card full"><div class="libraryHead"><div><div class="kicker">RUANG KARYA</div><h2>Temukan karya dari komunitas EA PLAN</h2><p class="muted">Baca karya sendiri maupun karya pengguna lain yang dipublikasikan.</p></div><button class="goldBtn" onclick="go('works')">Buat Karya</button></div><form class="librarySearch" onsubmit="searchPublicWorks(event)"><input class="input lightInput" id="publicSearch" placeholder="Cari karya, penulis, atau tag..." value="${esc(state.publicQuery||'')}"><select class="input lightInput" id="publicSort"><option value="latest">Terbaru</option><option value="popular">Terpopuler</option><option value="interesting">Menarik</option></select><button class="ghostBtn">Cari</button></form><div id="publicResults">${publicWorkSections(works)}</div></section>`}
function publicWorkSections(works){if(!works.length)return '<div class="emptyLibrary">Belum ada karya publik. Jadilah yang pertama menerbitkan karya.</div>';const latest=[...works].sort((a,b)=>new Date(b.published_at||b.created_at)-new Date(a.published_at||a.created_at)).slice(0,8),popular=[...works].sort((a,b)=>(b.view_count||0)-(a.view_count||0)).slice(0,8),interesting=[...works].sort((a,b)=>(b.like_count||0)+(b.view_count||0)*.2-(a.like_count||0)-(a.view_count||0)*.2).slice(0,8);return `<div class="workSection"><div class="sectionTitle"><h3>Terbaru</h3><button onclick="go('works')">Lihat semua →</button></div><div class="workSlider">${latest.map(workCard).join('')}</div></div><div class="workSection"><div class="sectionTitle"><h3>Terpopuler</h3><span class="muted">Berdasarkan jumlah dibaca</span></div><div class="workSlider">${popular.map(workCard).join('')}</div></div><div class="workSection"><div class="sectionTitle"><h3>Menarik</h3><span class="muted">Karya yang sedang mendapat perhatian</span></div><div class="workSlider">${interesting.map(workCard).join('')}</div></div>`}
function workCard(w){const cover=w.cover_url||A+'logo.png';return `<article class="workCard" onclick="readWork('${w.id}')"><img src="${esc(cover)}" alt="Cover ${esc(w.title)}"><div class="workCardBody"><span class="workType">${esc(w.type||'Tulisan')}</span><h4>${esc(w.title)}</h4><p>${esc((w.description||'').slice(0,90))}</p><div class="workMeta"><span>${esc(w.author_name||'Kreator')}</span><span>◉ ${w.view_count||0}</span></div><div class="tagRow">${(w.tags||[]).slice(0,3).map(t=>`<span>#${esc(t)}</span>`).join('')}</div></div></article>`}
async function loadPublicWorks(query='',sort='latest'){state.publicQuery=query;let q=db.from('works').select('*').eq('visibility','public').eq('status','published');if(query)q=q.or(`title.ilike.%${query}%,description.ilike.%${query}%,author_name.ilike.%${query}%`);if(sort==='popular')q=q.order('view_count',{ascending:false});else if(sort==='interesting')q=q.order('like_count',{ascending:false}).order('view_count',{ascending:false});else q=q.order('published_at',{ascending:false});const {data,error}=await q.limit(80);if(error){console.error(error);state.publicWorks=[]}else state.publicWorks=data||[]}
async function searchPublicWorks(e){e.preventDefault();const q=document.querySelector('#publicSearch')?.value.trim()||'';const sort=document.querySelector('#publicSort')?.value||'latest';await loadPublicWorks(q,sort);const box=document.querySelector('#publicResults');if(box)box.innerHTML=publicWorkSections(state.publicWorks||[])}
function works(){if(state.publicWorks===null){loadPublicWorks(state.publicQuery||'').then(()=>{if(state.active==='works')renderApp()});return '<div class="grid"><article class="card full"><div class="metric">Memuat ruang karya…</div></article></div>'}const mine=state.cache.works||[];return `<div class="grid"><article class="card full"><div class="libraryHead"><div><div class="kicker">KARYA</div><h1 class="pageTitle">Buat dan terbitkan karya.</h1><p class="muted">Tulis buku, komik/galeri, webtoon, audio, atau bagikan file. Karya dapat disimpan sebagai draft atau dipublikasikan untuk komunitas.</p></div><button class="goldBtn" onclick="createWorkForm()">＋ Buat Karya</button></div><form class="librarySearch" onsubmit="searchPublicWorks(event)"><input class="input lightInput" id="publicSearch" placeholder="Cari karya, penulis, atau tag..." value="${esc(state.publicQuery||'')}"><select class="input lightInput" id="publicSort"><option value="latest">Terbaru</option><option value="popular">Terpopuler</option><option value="interesting">Menarik</option></select><button class="ghostBtn">Cari</button></form><div class="sectionTitle"><h3>Karya Publik</h3><span class="muted">${(state.publicWorks||[]).length} karya ditemukan</span></div><div class="workGrid">${(state.publicWorks||[]).map(workCard).join('')||'<div class="emptyLibrary">Belum ada karya publik.</div>'}</div></article><article class="card full"><div class="sectionTitle"><h3>Karya Saya</h3><span class="muted">Draft dan karya terbit</span></div>${mine.map(myWorkRow).join('')||'<p class="muted">Belum ada karya. Tekan “Buat Karya” untuk mulai.</p>'}</article></div>`}
function myWorkRow(w){return `<div class="myWorkRow"><img src="${esc(w.cover_url||A+'logo.png')}"><div class="myWorkInfo"><strong>${esc(w.title)}</strong><span>${esc(w.type||'Tulisan')} · ${w.status==='published'?'Dipublikasikan':'Draft'} · ${w.view_count||0} dibaca</span><small>${(w.tags||[]).map(t=>'#'+esc(t)).join(' ')}</small></div><div class="rowActions"><button class="smallBtn" onclick="editWork('${w.id}')">Edit</button><button class="smallBtn" onclick="manageChapters('${w.id}')">Bab</button><button class="smallBtn danger" onclick="deleteWork('${w.id}')">Hapus</button></div></div>`}
function createWorkForm(existing=null){const w=existing||{title:'',description:'',type:'Tulisan',tags:[],series:'',allow_comments:true,mature:false,support_type:'Satuan',price_points:0,cover_url:'',status:'draft',visibility:'private'};app.innerHTML=`<div class="appShell"><main class="main"><header class="top"><div><button class="link" onclick="go('works')">← Kembali</button><h2>${existing?'Edit Karya':'Buat Karya'}</h2></div></header><div class="grid"><article class="card full"><form class="form lightForm" onsubmit="saveWork(event,'${existing?.id||''}')"><label class="label lightLabel">Jenis karya</label><select class="input lightInput" id="wType"><option ${w.type==='Tulisan'?'selected':''}>Tulisan</option><option ${w.type==='Komik/Galeri'?'selected':''}>Komik/Galeri</option><option ${w.type==='Webtoon'?'selected':''}>Webtoon</option><option ${w.type==='Audio'?'selected':''}>Audio</option><option ${w.type==='File Download'?'selected':''}>File Download</option></select><label class="label lightLabel">Cover</label><input class="input lightInput" id="wCover" type="file" accept="image/*"><div class="coverPreview">${w.cover_url?`<img src="${esc(w.cover_url)}">`:'<span>Unggah cover karya</span>'}</div><label class="label lightLabel">Judul (wajib)</label><input class="input lightInput" id="wTitle" value="${esc(w.title)}" required><label class="label lightLabel">Deskripsi singkat</label><textarea class="input lightInput" id="wDesc" rows="5">${esc(w.description||'')}</textarea><label class="label lightLabel">Seri</label><input class="input lightInput" id="wSeries" value="${esc(w.series||'')}" placeholder="Opsional, misalnya: Perjalanan Ari"><label class="label lightLabel">Tag</label><input class="input lightInput" id="wTags" value="${esc((w.tags||[]).join(', '))}" placeholder="novel, motivasi, romance"><label class="label lightLabel">Komentar</label><label class="switchLine"><input id="wComments" type="checkbox" ${w.allow_comments?'checked':''}> Aktifkan komentar</label><label class="label lightLabel">Konten dewasa</label><label class="switchLine"><input id="wMature" type="checkbox" ${w.mature?'checked':''}> Tandai sebagai konten dewasa</label><div class="supportBox"><h3>Tipe dan Harga Dukungan</h3><p class="muted">Siapkan opsi dukungan untuk karya. Pembayaran nyata memerlukan payment gateway pada tahap berikutnya.</p><select class="input lightInput" id="wSupport"><option ${w.support_type==='Satuan'?'selected':''}>Satuan</option><option ${w.support_type==='Gratis'?'selected':''}>Gratis</option><option ${w.support_type==='Paket'?'selected':''}>Paket</option></select><input class="input lightInput" id="wPrice" type="number" min="0" value="${Number(w.price_points||0)}" placeholder="Harga / poin dukungan"></div><div class="publishBox"><label class="label lightLabel">Publikasi</label><select class="input lightInput" id="wVisibility"><option value="private" ${w.visibility!=='public'?'selected':''}>Pribadi / Draft</option><option value="public" ${w.visibility==='public'?'selected':''}>Publikasikan untuk komunitas</option></select></div><button class="goldBtn" type="submit">${existing?'Simpan perubahan':'Buat Karya'}</button></form></article></div></main></div>`}
async function uploadWorkCover(file,workId){if(!file)return null;if(!file.type.startsWith('image/'))throw new Error('Cover harus berupa gambar.');if(file.size>8*1024*1024)throw new Error('Ukuran cover maksimal 8 MB.');const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';const path=`${state.user.id}/${workId}.${ext}`;const {error}=await db.storage.from('work-media').upload(path,file,{upsert:true,contentType:file.type});if(error)throw error;return db.storage.from('work-media').getPublicUrl(path).data.publicUrl}
async function saveWork(e,id){e.preventDefault();try{const author_name=state.profile?.name||'Kreator',title=document.querySelector('#wTitle').value.trim(),description=document.querySelector('#wDesc').value.trim(),type=document.querySelector('#wType').value,tags=document.querySelector('#wTags').value.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean).slice(0,12),series=document.querySelector('#wSeries').value.trim(),allow_comments=document.querySelector('#wComments').checked,mature=document.querySelector('#wMature').checked,support_type=document.querySelector('#wSupport').value,price_points=Number(document.querySelector('#wPrice').value||0),visibility=document.querySelector('#wVisibility').value;let work;if(id){const {data,error}=await db.from('works').update({author_name,title,description,type,tags,series,allow_comments,mature,support_type,price_points,visibility,status:visibility==='public'?'published':'draft',published_at:visibility==='public'?new Date().toISOString():null,updated_at:new Date().toISOString()}).eq('id',id).eq('user_id',state.user.id).select('*').single();if(error)throw error;work=data}else{const {data,error}=await db.from('works').insert({user_id:state.user.id,author_name,title,description,type,tags,series,allow_comments,mature,support_type,price_points,visibility,status:visibility==='public'?'published':'draft',published_at:visibility==='public'?new Date().toISOString():null}).select('*').single();if(error)throw error;work=data}const file=document.querySelector('#wCover').files[0];if(file){const url=await uploadWorkCover(file,work.id);const {error}=await db.from('works').update({cover_url:url}).eq('id',work.id).eq('user_id',state.user.id);if(error)throw error}await loadData();alert(visibility==='public'?'Karya berhasil dipublikasikan.':'Karya tersimpan sebagai draft.');go('works')}catch(err){alert(err.message||String(err))}}
async function editWork(id){const w=state.cache.works.find(x=>x.id===id);if(w)createWorkForm(w)}
async function deleteWork(id){if(!confirm('Hapus karya dan seluruh babnya?'))return;const {error}=await db.from('works').delete().eq('id',id).eq('user_id',state.user.id);if(error)alert(error.message);else{await loadData();go('works')}}
async function manageChapters(workId){const w=state.cache.works.find(x=>x.id===workId);if(!w)return;const {data,error}=await db.from('work_chapters').select('*').eq('work_id',workId).eq('user_id',state.user.id).order('chapter_number',{ascending:true});if(error){alert(error.message);return}app.innerHTML=`<div class="appShell"><main class="main"><header class="top"><div><button class="link" onclick="go('works')">← Karya</button><h2>${esc(w.title)}</h2></div><button class="goldBtn" onclick="chapterForm('${workId}')">＋ Tambah Bab</button></header><div class="grid"><article class="card full"><div class="sectionTitle"><h3>Daftar Bab</h3><span class="muted">${data.length} bab</span></div>${data.map(ch=>`<div class="chapterRow"><div><strong>Bab ${ch.chapter_number} · ${esc(ch.title)}</strong><p class="muted">${esc((ch.content||'').replace(/<[^>]*>/g,'').slice(0,120))}</p></div><button class="smallBtn" onclick="chapterForm('${workId}','${ch.id}')">Edit</button></div>`).join('')||'<p class="muted">Belum ada bab.</p>'}</article></div></main></div>`}
async function chapterForm(workId,id=''){let ch={title:'',content:'',chapter_number:1};if(id){const {data,error}=await db.from('work_chapters').select('*').eq('id',id).eq('user_id',state.user.id).single();if(error){alert(error.message);return}ch=data}else{const {data}=await db.from('work_chapters').select('chapter_number').eq('work_id',workId).eq('user_id',state.user.id).order('chapter_number',{ascending:false}).limit(1);ch.chapter_number=(data?.[0]?.chapter_number||0)+1}app.innerHTML=`<div class="appShell"><main class="main"><header class="top"><div><button class="link" onclick="manageChapters('${workId}')">← Bab</button><h2>${id?'Edit Bab':'Tambah Bab'}</h2></div></header><div class="grid"><article class="card full"><form class="form lightForm" onsubmit="saveChapter(event,'${workId}','${id}')"><input class="input lightInput" id="chNumber" type="number" min="1" value="${ch.chapter_number}" required><input class="input lightInput" id="chTitle" value="${esc(ch.title)}" placeholder="Judul bab" required><textarea class="input lightInput workEditor" id="chContent" rows="20" placeholder="Tulis isi bab di sini...">${esc(ch.content||'')}</textarea><button class="goldBtn">Simpan Bab</button></form></article></div></main></div>`}
async function saveChapter(e,workId,id){e.preventDefault();const payload={work_id:workId,user_id:state.user.id,chapter_number:Number(document.querySelector('#chNumber').value),title:document.querySelector('#chTitle').value.trim(),content:document.querySelector('#chContent').value};let res=id?await db.from('work_chapters').update(payload).eq('id',id).eq('user_id',state.user.id):await db.from('work_chapters').insert(payload);if(res.error)alert(res.error.message);else manageChapters(workId)}
async function readWork(id){const {data:w,error}=await db.from('works').select('*').eq('id',id).eq('status','published').eq('visibility','public').single();if(error){alert('Karya tidak ditemukan atau belum dipublikasikan.');return}await db.rpc('increment_work_view',{p_work_id:id});const {data:chapters}=await db.from('work_chapters').select('*').eq('work_id',id).order('chapter_number',{ascending:true});app.innerHTML=`<div class="appShell"><main class="main"><header class="top"><div><button class="link" onclick="go('home')">← Beranda</button><h2>Baca Karya</h2></div></header><article class="reader"><img class="readerCover" src="${esc(w.cover_url||A+'logo.png')}"><div class="readerInfo"><span class="workType">${esc(w.type)}</span><h1>${esc(w.title)}</h1><p>${esc(w.description||'')}</p><div class="tagRow">${(w.tags||[]).map(t=>`<span>#${esc(t)}</span>`).join('')}</div><div class="readerMeta">${esc(w.author_name||'Kreator')} · ◉ ${(w.view_count||0)+1} dibaca</div></div><div class="chapterList"><h3>Daftar Isi</h3>${(chapters||[]).map((c,i)=>`<button onclick="openChapter('${c.id}')"><span>Bab ${c.chapter_number}</span><strong>${esc(c.title)}</strong></button>`).join('')||'<p class="muted">Belum ada bab.</p>'}</div></article></main></div>`}
async function openChapter(id){const {data:c,error}=await db.from('work_chapters').select('*, works!inner(title,status,visibility)').eq('id',id).single();if(error){alert(error.message);return}app.innerHTML=`<div class="appShell"><main class="main"><header class="top"><div><button class="link" onclick="readWork('${c.work_id}')">← Daftar Isi</button><h2>${esc(c.works.title)}</h2></div></header><article class="readerText"><div class="kicker">BAB ${c.chapter_number}</div><h1>${esc(c.title)}</h1><div class="readingContent">${esc(c.content).replace(/\n/g,'<br>')}</div></article></main></div>`}
async function saveDailyQuote(e){e.preventDefault();const quote=document.querySelector('#dailyQuote').value.trim();const {error}=await db.from('app_settings').update({daily_quote:quote,updated_at:new Date().toISOString()}).eq('id',1);if(error)alert(error.message);else{state.cache.settings={...state.cache.settings,daily_quote:quote};alert('Quote harian diperbarui.');renderApp()}}
async function addTask(e){e.preventDefault();const title=document.querySelector('#taskTitle').value.trim(),due=document.querySelector('#taskDate').value||null;const {error}=await db.from('tasks').insert({user_id:state.user.id,title,due_date:due});if(error)return alert(error.message);await dashboard();go('planning')}
async function completeTask(id){const t=state.cache.tasks.find(x=>x.id===id);if(!t)return;const {error}=await db.from('tasks').update({completed:!t.completed,updated_at:new Date().toISOString()}).eq('id',id).eq('user_id',state.user.id);if(error)alert(error.message);else{await loadData();renderApp()}}
async function addGoal(e){e.preventDefault();const title=document.querySelector('#goalTitle').value.trim(),due=document.querySelector('#goalDate').value||null,description=document.querySelector('#goalDesc').value.trim();const {error}=await db.from('goals').insert({user_id:state.user.id,title,due_date:due,description});if(error)return alert(error.message);await dashboard();go('goals')}
async function updateGoalProgress(id,value){const {error}=await db.from('goals').update({progress:Number(value),status:Number(value)>=100?'completed':'active',updated_at:new Date().toISOString()}).eq('id',id).eq('user_id',state.user.id);if(error)alert(error.message);else{const g=state.cache.goals.find(x=>x.id===id);if(g){g.progress=Number(value);g.status=Number(value)>=100?'completed':'active';}}}
async function toggleGoal(id,status){const {error}=await db.from('goals').update({status:status==='completed'?'active':'completed',progress:status==='completed'?0:100,updated_at:new Date().toISOString()}).eq('id',id).eq('user_id',state.user.id);if(error)alert(error.message);else{await loadData();renderApp()}}
async function addTextItem(e,type){e.preventDefault();const title=document.querySelector('#itemTitle').value.trim(),body=document.querySelector('#itemBody').value.trim();const table=type==='journal'?'journal_entries':'ideas';const {error}=await db.from(table).insert({user_id:state.user.id,title,body});if(error)return alert(error.message);await dashboard();go(type)}
async function addProject(e){e.preventDefault();const title=document.querySelector('#projectTitle').value.trim(),description=document.querySelector('#projectDesc').value.trim();const {error}=await db.from('projects').insert({user_id:state.user.id,title,description});if(error)return alert(error.message);await dashboard();go('projects')}
async function updateProjectProgress(id,value){const {error}=await db.from('projects').update({progress:Number(value),status:Number(value)>=100?'completed':'active',updated_at:new Date().toISOString()}).eq('id',id).eq('user_id',state.user.id);if(error)alert(error.message);else{const p=state.cache.projects.find(x=>x.id===id);if(p){p.progress=Number(value);p.status=Number(value)>=100?'completed':'active';}}}
async function removeItem(type,id){if(!confirm('Hapus item ini?'))return;const table=type==='journal'?'journal_entries':type==='ideas'?'ideas':type;const {error}=await db.from(table).delete().eq('id',id).eq('user_id',state.user.id);if(error)alert(error.message);else{await dashboard();go(state.active)}}
async function saveProfile(e){e.preventDefault();const payload={name:document.querySelector('#pName').value.trim(),username:document.querySelector('#pUsername').value.trim(),bio:document.querySelector('#pBio').value.trim(),updated_at:new Date().toISOString()};const {error}=await db.from('profiles').update(payload).eq('id',state.user.id);if(error)alert(error.message);else{state.profile={...state.profile,...payload};alert('Profil tersimpan.');renderApp()}}
async function logout(){await db.auth.signOut();state={session:null,user:null,profile:null,selected:[],onStep:1,active:'home',loading:false,cache:{goals:[],tasks:[],journal:[],ideas:[],projects:[],works:[],settings:null},publicWorks:null,publicQuery:''};welcome()}
function go(id){state.active=id;renderApp()}
db.auth.onAuthStateChange(async(_event,session)=>{state.session=session;state.user=session?.user||null;if(!session){if(!document.querySelector('.authShell'))welcome()}});
(async()=>{try{await loadSession();splash()}catch(e){console.error(e);app.innerHTML=`<div class="authPanel authFull"><div class="authBox">${msg('EA PLAN gagal memuat. Periksa koneksi dan konfigurasi Supabase.')}</div></div>`}})();


/* ================= EA PLAN FINAL SPEC ================= */
const FINAL_NAV=[['home','⌂','Beranda'],['works','▣','Karya'],['create','＋','Buat'],['stats','◒','Statistik'],['profile','◉','Profil']];
const FINAL_TITLES={home:'EA PLAN',works:'Karya Publik',create:'Buat Karya',stats:'Statistik',profile:'Profil',about:'Tentang EA PLAN',explore:'Jelajahi',collections:'Koleksi',guide:'Panduan'};
state.community=state.community||{works:[],comments:[],snapshots:[],query:''};
function finalAvatar(){return state.profile?.avatar_url?`<img src="${esc(state.profile.avatar_url)}" alt="Profil">`:initials()}
async function loadCommunity(){
  const q=db.from('works').select('*').eq('status','published').eq('visibility','public').order('published_at',{ascending:false}).limit(100);
  const {data:works,error}=await q;
  if(!error) state.community.works=works||[];
  const {data:comments}=await db.from('work_comments').select('id,work_id,user_id,body,created_at,works(title,cover_url,author_name)').order('created_at',{ascending:false}).limit(20);
  state.community.comments=comments||[];
}
function finalHeader(id){
 const av=finalAvatar();
 return `<header class="top finalTop"><div class="brandHeader"><img class="headerLogo" src="${A}logoea.png" alt="EA PLAN"><div><div class="kicker">RUANG PERJALANAN</div><h2>${esc(FINAL_TITLES[id]||'EA PLAN')}</h2></div></div><button class="headerProfile" onclick="go('profile')" aria-label="Profil">${av}</button></header>`;
}
function finalShell(content,id='home'){
 const desktop=[['home','⌂','Beranda'],['works','▣','Karya'],['create','＋','Buat'],['stats','◒','Statistik'],['profile','◉','Profil']];
 return `<div class="appShell finalShell"><aside class="side"><div class="sideBrand"><img src="${A}logoea.png"><span>EA PLAN</span></div><nav class="nav">${desktop.map(x=>`<button class="${id===x[0]?'active':''}" onclick="go('${x[0]}')">${x[1]}&nbsp;&nbsp;${x[2]}</button>`).join('')}<div class="navDivider"></div><button onclick="go('about')">◎&nbsp;&nbsp;Tentang EA PLAN</button><button onclick="go('explore')">⌕&nbsp;&nbsp;Jelajahi</button><button onclick="go('collections')">▤&nbsp;&nbsp;Koleksi</button><button onclick="go('guide')">?&nbsp;&nbsp;Panduan</button><button onclick="logout()">↪&nbsp;&nbsp;Keluar</button></nav></aside><main class="main">${finalHeader(id)}${content}</main><nav class="mobileNav">${desktop.map(x=>`<button class="${id===x[0]?'active':''}" onclick="go('${x[0]}')"><b>${x[1]}</b>${x[2]}</button>`).join('')}</nav></div>`;
}
function renderApp(){
 let id=state.active||'home',content='';
 if(id==='home') content=finalHome();
 else if(id==='works') content=finalWorks();
 else if(id==='create') content=finalCreate();
 else if(id==='stats') content=finalStats();
 else if(id==='profile') content=finalProfile();
 else if(id==='about') content=finalAbout();
 else if(id==='explore') content=finalExplore();
 else if(id==='collections') content=finalCollections();
 else if(id==='guide') content=finalGuide();
 else if(['planning','goals','journal','ideas','projects','journey'].includes(id)) content=window[id]();
 else content=finalHome();
 app.innerHTML=finalShell(content,id);
 if(id==='home' && !state.communityLoaded){state.communityLoaded=true;loadCommunity().then(()=>{if(state.active==='home')renderApp()})}
 if(id==='stats') loadStatsSnapshot();
}
function finalHome(){
 const p=state.profile||{}, quote=state.cache.settings?.daily_quote||'Setiap karya besar berawal dari satu langkah kecil yang terencana.';
 return `<div class="homeFinal"><section class="card welcomeFinal"><div class="kicker">SELAMAT DATANG, ${esc((p.name||'KREATOR').toUpperCase())}</div><h1 class="heroTitle">Rancang hidupmu.<br>Rawat perjalananmu.</h1><p class="muted">Ruang privat untuk perjalananmu, sekaligus ruang publik untuk karya yang ingin kamu bagikan.</p></section><section class="quoteCard card"><div class="kicker">QUOTE HARI INI</div><blockquote>“${esc(quote)}”</blockquote><span>— EA PLAN —</span></section>${finalPublicSections()}</div>`;
}
function finalPublicSections(){
 const ws=state.community?.works||[];
 const latest=[...ws].sort((a,b)=>new Date(b.published_at||b.created_at)-new Date(a.published_at||a.created_at)).slice(0,8);
 const popular=[...ws].sort((a,b)=>(b.view_count||0)-(a.view_count||0)).slice(0,8);
 const interesting=[...ws].sort((a,b)=>(b.like_count||0)*2+(b.view_count||0)-(a.like_count||0)*2-(a.view_count||0)).slice(0,8);
 const comments=(state.community?.comments||[]).filter(c=>c.works).slice(0,8);
 return `<section class="publicBlock"><div class="sectionTitle"><div><div class="kicker">RUANG KARYA</div><h2>Temukan karya komunitas EA PLAN</h2></div><button class="textBtn" onclick="go('works')">Lihat semua →</button></div><div class="homeSearch"><input class="input lightInput" id="homePublicSearch" placeholder="Cari karya, penulis, atau tag..."><button class="ghostBtn" onclick="homeSearch()">Cari</button></div></section>${homeSlider('TERBARU','Karya yang baru dipublikasikan.',latest)}${homeSlider('TERPOPULER','Paling banyak dibaca komunitas.',popular)}${homeSlider('MENARIK DILIHAT','Karya yang sedang mendapat perhatian.',interesting)}${commentSlider(comments)}`;
}
function homeSlider(title,sub,arr){return `<section class="homeSection"><div class="sectionTitle"><div><h3>${title}</h3><span class="muted">${sub}</span></div><button class="textBtn" onclick="go('works')">Lihat semua</button></div><div class="workSlider homeWorkSlider">${arr.map(workCard).join('')||'<div class="emptyLibrary">Belum ada karya publik. Jadilah kreator pertama.</div>'}</div></section>`}
function commentSlider(arr){return `<section class="homeSection"><div class="sectionTitle"><div><h3>KOMENTAR MEREKA</h3><span class="muted">Komentar terbaru dari pembaca karya.</span></div><button class="textBtn" onclick="go('works')">Lihat semua</button></div><div class="commentSlider">${arr.map(c=>`<article class="commentCard"><div class="commentWork"><img src="${esc(c.works.cover_url||A+'logo.png')}"><div><strong>${esc(c.works.title)}</strong><small>${esc(c.works.author_name||'Kreator')}</small></div></div><p>“${esc(c.body)}”</p><small>${new Date(c.created_at).toLocaleDateString('id-ID')}</small></article>`).join('')||'<div class="emptyLibrary">Belum ada komentar karya.</div>'}</div></section>`}
function homeSearch(){const q=document.querySelector('#homePublicSearch')?.value.trim()||'';state.community.query=q;state.active='works';renderApp();setTimeout(()=>{const i=document.querySelector('#publicSearch');if(i){i.value=q;searchPublicWorks({preventDefault(){}})}},0)}
function finalWorks(){
 const ws=state.community?.works||[], mine=state.cache.works||[];
 return `<div class="libraryPage"><section class="libraryHero card"><div><div class="kicker">KARYA PUBLIK</div><h1 class="pageTitle">Buat, terbitkan, dan temukan karya.</h1><p class="muted">Ruang untuk buku, tulisan, komik, webtoon, audio, dan karya digital lain milik komunitas EA PLAN.</p></div><button class="goldBtn" onclick="createWorkForm()">＋ Buat Karya Baru</button></section><section class="card full"><div class="librarySearch"><input class="input lightInput" id="publicSearch" placeholder="Cari karya, penulis, atau tag..." value="${esc(state.community.query||'')}"><select class="input lightInput" id="publicSort"><option value="latest">Terbaru</option><option value="popular">Terpopuler</option><option value="interesting">Menarik</option></select><button class="ghostBtn" onclick="searchPublicFinal(event)">Cari</button></div><div class="categoryPills"><button class="active">Semua</button><button>Buku</button><button>Komik</button><button>Webtoon</button><button>Audio</button><button>File</button></div><div class="sectionTitle"><h3>Hasil Karya</h3><span class="muted">${ws.length} karya publik</span></div><div class="workGrid">${ws.map(workCard).join('')||'<div class="emptyLibrary">Belum ada karya publik.</div>'}</div></section><section class="card full"><div class="sectionTitle"><h3>Karya Saya</h3><button class="textBtn" onclick="createWorkForm()">＋ Karya baru</button></div>${mine.map(myWorkRow).join('')||'<p class="muted">Belum ada karya. Mulai dari satu karya kecil.</p>'}</section></div>`;
}
async function searchPublicFinal(e){e.preventDefault();const q=document.querySelector('#publicSearch')?.value.trim()||'';const sort=document.querySelector('#publicSort')?.value||'latest';state.community.query=q;await loadPublicWorks(q,sort);state.community.works=state.publicWorks||[];renderApp()}
function finalCreate(){return `<div class="createPage"><section class="card full"><div class="kicker">BUAT KARYA BARU</div><h1 class="pageTitle">Jadikan ide menjadi sesuatu yang bisa dibaca.</h1><p class="muted">Pilih jenis karya lalu isi detail, bab, cover, dan pengaturan publikasi.</p><div class="createChoices"><button onclick="createWorkForm()"><b>▣</b><strong>Buku / Tulisan</strong><small>Novel, cerita, esai, puisi</small></button><button onclick="createWorkForm()"><b>▧</b><strong>Komik / Galeri</strong><small>Visual dan rangkaian gambar</small></button><button onclick="createWorkForm()"><b>▤</b><strong>Webtoon</strong><small>Episode visual vertikal</small></button><button onclick="createWorkForm()"><b>◉</b><strong>Audio</strong><small>Podcast, narasi, suara</small></button><button onclick="createWorkForm()"><b>↥</b><strong>File Download</strong><small>Bagikan file karya</small></button></div></section><section class="card full"><div class="kicker">ALUR KARYA</div><div class="flow"><span>1. Buat</span><i>→</i><span>2. Tulis</span><i>→</i><span>3. Simpan Draft</span><i>→</i><span>4. Publikasikan</span></div></section></div>`}
async function loadStatsSnapshot(){if(!state.user)return;const goals=state.cache.goals||[];const progress=goals.length?Math.round(goals.reduce((s,g)=>s+Number(g.progress||0),0)/goals.length):0;const today=new Date().toISOString().slice(0,10);await db.from('progress_snapshots').upsert({user_id:state.user.id,snapshot_date:today,progress},{onConflict:'user_id,snapshot_date'});const {data}=await db.from('progress_snapshots').select('*').eq('user_id',state.user.id).order('snapshot_date',{ascending:false}).limit(7);state.community.snapshots=(data||[]).reverse();renderStatsChart();}
function finalStats(){const c=state.cache,goals=c.goals||[],progress=goals.length?Math.round(goals.reduce((s,g)=>s+Number(g.progress||0),0)/goals.length):0;return `<div class="statsPage"><section class="card statHero"><div class="kicker">PROGRESS KESELURUHAN</div><div class="statBig">${progress}%</div><div class="chartWrap" id="statsChart">${simpleChart(state.community.snapshots||[],progress)}</div></section><section class="statsCards"><article class="card"><div class="kicker">TARGET AKTIF</div><div class="metric">${goals.filter(g=>g.status!=='completed').length}</div><p class="muted">Target yang sedang kamu jalankan.</p></article><article class="card"><div class="kicker">PROJECTS</div><div class="metric">${(c.projects||[]).length}</div><p class="muted">Ruang karya yang sedang tumbuh.</p></article><article class="card"><div class="kicker">JOURNAL</div><div class="metric">${(c.journal||[]).length}</div><p class="muted">Catatan perjalananmu.</p></article></section><section class="card statSummary"><div class="kicker">RINGKASAN</div><p>Perjalananmu sedang dibangun sedikit demi sedikit. Statistik ini membantu melihat progres keseluruhan, target, karya, proyek, dan refleksi tanpa kehilangan nuansa perjalanan EA PLAN.</p></section></div>`}
function simpleChart(arr,current){if(!arr.length)return `<div class="chartEmpty"><span>Belum cukup riwayat untuk grafik.</span><b>${current}% hari ini</b></div>`;return `<div class="barChart">${arr.map(x=>`<div class="barCol"><b>${x.progress}%</b><i style="height:${Math.max(8,Number(x.progress))}%"></i><small>${new Date(x.snapshot_date).toLocaleDateString('id-ID',{weekday:'short'}).replace('.','')}</small></div>`).join('')}</div>`}
function renderStatsChart(){const el=document.querySelector('#statsChart');if(el){const goals=state.cache.goals||[],p=goals.length?Math.round(goals.reduce((s,g)=>s+Number(g.progress||0),0)/goals.length):0;el.innerHTML=simpleChart(state.community.snapshots||[],p)}}
function finalProfile(){const p=state.profile||{},c=state.cache,avatar=p.avatar_url?`<img src="${esc(p.avatar_url)}" alt="Foto profil">`:`<span>${initials()}</span>`;const works=(c.works||[]),pub=works.filter(w=>w.status==='published');return `<div class="profileFinal"><section class="card profileIdentityCard"><div class="profileAvatarLarge">${avatar}<label class="cameraBtn">＋<input type="file" accept="image/*" onchange="uploadProfileMedia('avatar',this)"></label></div><div class="profileMainInfo"><div class="kicker">PROFIL KREATOR</div><h1>${esc(p.name||'Kreator')}</h1><p class="handle">@${esc(p.username||'username')}</p><p class="bioText">${esc(p.bio||'Belum ada bio.')}</p><button class="goldBtn" onclick="document.querySelector('#pName')?.focus()">Edit Profil</button></div><div class="profileStats"><span><b>${pub.length}</b>Karya</span><span><b>0</b>Pengikut</span><span><b>0</b>Mengikuti</span></div></section><section class="card profileMedia"><div class="kicker">MEDIA PROFIL</div><div class="mediaPreview"><img src="${esc(mediaUrl(p.background_url,DEFAULT_BG))}" alt="Background profil"></div><div class="mediaActions"><label class="mediaBtn">Pilih background<input type="file" accept="image/*" onchange="uploadProfileMedia('background',this)"></label><button class="smallBtn" onclick="resetBackground()">Gunakan default</button></div></section><section class="card"><div class="kicker">DATA PROFIL</div><form class="form lightForm" onsubmit="saveProfileFinal(event)"><input class="input lightInput" id="pName" value="${esc(p.name||'')}" placeholder="Nama" required><input class="input lightInput" id="pUsername" value="${esc(p.username||'')}" placeholder="Username" required><textarea class="input lightInput" id="pBio" rows="5" placeholder="Bio">${esc(p.bio||'')}</textarea><button class="goldBtn">Simpan profil</button></form></section><section class="card"><div class="sectionTitle"><h2>Karya saya</h2><button class="goldBtn" onclick="createWorkForm()">＋ Karya baru</button></div>${pub.map(myWorkRow).join('')||'<p class="muted">Belum ada karya yang dipublikasikan.</p>'}</section><section class="card"><div class="sectionTitle"><h2>Lainnya</h2></div><div class="moreGrid"><button onclick="go('works')"><b>▣</b><span><strong>Karya Publik</strong><small>Kelola karya, buat baru, lihat statistik</small></span>›</button><button onclick="go('ideas')"><b>✦</b><span><strong>Ide & Catatan</strong><small>Simpan ide, rencana, dan catatan penting</small></span>›</button><button onclick="go('projects')"><b>□</b><span><strong>Proyek</strong><small>Kelola proyek jangka panjang</small></span>›</button><button onclick="go('journal')"><b>✎</b><span><strong>Journal</strong><small>Catatan perjalanan dan refleksi harian</small></span>›</button><button onclick="go('about')"><b>◎</b><span><strong>Tentang EA PLAN</strong><small>Cerita, nilai, dan cara terhubung</small></span>›</button><button onclick="go('collections')"><b>▤</b><span><strong>Koleksi & Bookmark</strong><small>Karya yang ingin kamu baca kembali</small></span>›</button><button onclick="go('guide')"><b>?</b><span><strong>Panduan</strong><small>Cara membuat dan menerbitkan karya</small></span>›</button><button onclick="logout()"><b>↪</b><span><strong>Keluar</strong><small>Keluar dari akun EA PLAN</small></span>›</button></div></section></div>`}
async function saveProfileFinal(e){e.preventDefault();const name=document.querySelector('#pName').value.trim(),username=document.querySelector('#pUsername').value.trim(),bio=document.querySelector('#pBio').value.trim();let r=await db.from('profiles').update({name,username}).eq('id',state.user.id);if(r.error){alert(r.error.message);return}let b=await db.from('profiles').update({bio}).eq('id',state.user.id);if(b.error){alert('Nama dan username tersimpan, tetapi Bio belum tersimpan. Jalankan migrasi SQL final lalu coba lagi.');console.error(b.error);return}state.profile={...state.profile,name,username,bio};renderApp()}
function finalAbout(){return `<div class="infoPage"><section class="card"><div class="kicker">TENTANG KAMI</div><h1 class="pageTitle">Setiap karya besar berawal dari satu langkah kecil yang terencana.</h1><p>EA PLAN hadir sebagai ruang bagi para kreator untuk merajut mimpi, merangkai cerita, dan merawat setiap perjalanan hidup. Ini bukan sekadar aplikasi pencatat jadwal, melainkan rumah bagi ide-ide liar, refleksi harian, dan peta jalan untuk mewujudkan masa depan.</p><p>Inisiatif ini lahir dari kisah <strong>Aritox</strong>—seorang pemimpi yang mendambakan tempat privat untuk mendokumentasikan karya dan lika-liku kehidupannya. Dari kebutuhan personal itu, EA PLAN bertransformasi menjadi sebuah gerakan: wadah untuk merancang strategi, mengukur setiap target, dan mengubah usaha menjadi kenyataan yang hidup.</p><p>Karena hidup ini terlalu berharga untuk dijalani tanpa arah. Mari melangkah, merencanakan, dan bertumbuh bersama.</p></section><section class="card"><div class="kicker">MARI TERHUBUNG</div><h2>Punya cerita, masukan, atau butuh teman bertukar pikiran?</h2><p>Pintu kami selalu terbuka untukmu.</p><div class="contactList"><span>✉️ eaplan10@gmail.com</span><span>◎ Instagram: @eaplan_id</span><span>♪ TikTok: @eaplan_id</span></div></section></div>`}
function finalExplore(){const ws=state.community?.works||[];return `<div class="infoPage"><section class="card"><div class="kicker">JELAJAHI</div><h1 class="pageTitle">Temukan cerita berikutnya.</h1><p class="muted">Cari karya berdasarkan judul, penulis, atau tag.</p><div class="librarySearch"><input class="input lightInput" id="exploreSearch" placeholder="Cari karya, penulis, atau tag..."><button class="goldBtn" onclick="exploreSearch()">Cari</button></div></section><section class="card full"><div class="workGrid">${ws.map(workCard).join('')||'<div class="emptyLibrary">Belum ada karya publik.</div>'}</div></section></div>`}
function exploreSearch(){const q=document.querySelector('#exploreSearch')?.value.trim()||'';state.community.query=q;go('works');setTimeout(()=>{const i=document.querySelector('#publicSearch');if(i){i.value=q;searchPublicFinal({preventDefault(){}})}},0)}
function finalCollections(){return `<div class="infoPage"><section class="card"><div class="kicker">KOLEKSI</div><h1 class="pageTitle">Simpan karya yang ingin kamu baca kembali.</h1><p class="muted">Bookmark akan muncul di sini. Fitur interaksi publik aktif setelah migrasi sosial EA PLAN dijalankan.</p><div class="emptyLibrary">Belum ada koleksi tersimpan.</div></section></div>`}
function finalGuide(){return `<div class="infoPage"><section class="card"><div class="kicker">PANDUAN</div><h1 class="pageTitle">Dari ide menjadi karya.</h1><div class="guideSteps"><article><b>01</b><h3>Buat karya</h3><p>Pilih jenis karya, tambahkan judul, deskripsi, cover, dan tag.</p></article><article><b>02</b><h3>Tulis isi</h3><p>Gunakan menu Bab untuk menyusun isi karya secara bertahap.</p></article><article><b>03</b><h3>Simpan draft</h3><p>Draft tetap privat dan hanya dapat dikelola oleh pembuatnya.</p></article><article><b>04</b><h3>Publikasikan</h3><p>Ubah status menjadi publik agar karya dapat ditemukan dan dibaca komunitas.</p></article></div></section></div>`}
